import {improvementStats} from './improvement-stats.js';
import {locale} from './i18n.js';
import {createGoal,goalText,eligible} from './weekly-goal.js';
import {runBatch,ANALYSIS_METHOD} from './batch-analysis.js';
import {validateBackup} from './backup.js';
import {makeDeck,reviewSummary} from './repetition.js';
import {readAll,getRecord,putRecord,saveGame,personalStats,THEMES} from './archive.js';
import {escapeHTML as esc,getSettings,saveSettings} from './settings.js';
import {fetchProfile,syncArchive,fetchLatestGames} from './chess-api.js';
import {Chess} from './vendor/chess.js';
const $=id=>document.getElementById(id);let games=[],page=0,profile=null,controller=null;
const date=t=>new Date(t).toLocaleDateString(locale()),fixed=x=>x==null?'—':x.toFixed(1);
function stats(){const trend=improvementStats(games),r=trend.recent,p=trend.previous;const value=n=>n==null?'—':n.toFixed(1);$('improvementDetail').innerHTML=`<p>Ultime ${r.games} partite utili · ${r.moves} mosse fuori teoria</p><div class="stat-grid"><div class="stat"><span>Errori per 100 mosse</span><strong>${value(r.errors)}</strong></div><div class="stat"><span>Svarioni per 100 mosse</span><strong>${value(r.blunders)}</strong></div></div><p>${trend.comparable?`Rispetto alle 5 precedenti (${p.moves} mosse): precisione ${trend.delta.accuracy>=0?'+':''}${value(trend.delta.accuracy)} punti; errori ${trend.delta.errors>=0?'+':''}${value(trend.delta.errors)} e svarioni ${trend.delta.blunders>=0?'+':''}${value(trend.delta.blunders)} per 100 mosse. Meno errori è meglio.`:`Servono altre ${trend.remaining} partite utili per confrontare due gruppi di 5.`}</p><small>Solo partite concluse, con il tuo colore, analisi completa e almeno 10 mosse personali fuori teoria. Gli svarioni sono inclusi negli errori. I gruppi possono avere difficoltà e tempi di gioco diversi: il confronto è indicativo.</small>`;const s=personalStats(games);$('stats').innerHTML=[['Partite registrate',s.total],['Vinte / patte / perse',`${s.wins} / ${s.draws} / ${s.losses}`],['Precisione media',fixed(s.accuracy)],['Analisi personali complete',s.analyzed]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value}</strong></div>`).join('');const values=s.averages.slice(-20);$('trend').innerHTML=values.length?`<div class="trend-bars" role="img" aria-label="Precisione delle ultime ${values.length} partite analizzate">${values.map(v=>`<div title="${date(v.date)}: ${v.value.toFixed(1)}"><span>${v.value.toFixed(0)}</span><i style="height:${Math.max(3,v.value)}px"></i><small>${date(v.date).slice(0,5)}</small></div>`).join('')}</div>`:'<p>Analizza una partita e indica il tuo colore per iniziare.</p>';$('trendNote').textContent=(s.delta===null?'Servono 10 analisi personali complete per confrontare le ultime 5 con le 5 precedenti.':`Ultime 5 rispetto alle 5 precedenti: ${s.delta>=0?'+':''}${s.delta.toFixed(1)} punti di precisione. Non è una misura del tuo Elo.`)+` Confronto limitato al metodo di accuracy dell’analisi più recente; i dati precedenti restano nell’archivio. ${s.total-s.identified} partite senza colore personale. Esiti calcolati su ${s.finished} partite concluse.`;const entries=Object.entries(s.themes).sort((a,b)=>b[1]-a[1]);$('themes').innerHTML=entries.some(([,n])=>n)?entries.map(([key,n])=>`<div class="theme-row"><span>${THEMES[key]}</span><strong>${n}</strong></div>`).join(''):'<p>Nessun errore personale ancora disponibile. Le partite importate vanno prima analizzate.</p>'}
function list(){const q=$('gameSearch').value.toLowerCase(),source=$('sourceFilter').value;const filtered=games.filter(g=>(source==='all'||g.source===source)&&JSON.stringify(g.headers).toLowerCase().includes(q)).sort((a,b)=>b.playedAt-a.playedAt);page=Math.min(page,Math.max(0,Math.ceil(filtered.length/15)-1));const slice=filtered.slice(page*15,page*15+15);$('archiveList').innerHTML=slice.length?slice.map(g=>`<article class="archive-row"><div><strong>${esc(g.headers.White||'Bianco')} <span class="muted">vs</span> ${esc(g.headers.Black||'Nero')}</strong><p>${date(g.playedAt)} · ${esc(g.source)} · ${esc(g.headers.Result||'*')} · ${g.analysis?.complete?'Analizzata':'Da completare / analizzare'}</p></div><button class="secondary" data-open-game="${esc(g.id)}">Apri →</button></article>`).join(''):'<div class="empty-state"><h3>Qui comincia il tuo archivio.</h3><p>Gioca con il coach, importa un PGN o collega un profilo Chess.com.</p><a href="coach.html">Gioca una partita →</a></div>';$('pageInfo').textContent=`${filtered.length} partite · pagina ${page+1} / ${Math.max(1,Math.ceil(filtered.length/15))}`;$('previousPage').disabled=page===0;$('nextPage').disabled=(page+1)*15>=filtered.length;document.querySelectorAll('[data-open-game]').forEach(b=>b.onclick=()=>{const g=games.find(g=>g.id===b.dataset.openGame);try{localStorage.setItem('plystreak-review-import',g.pgn);localStorage.setItem('plystreak-review-id',g.id);localStorage.setItem('plystreak-review-side',g.side||'');location.href='index.html?training=1'}catch{$('hubStatus').textContent='Memoria temporanea non disponibile. Esporta il backup e conserva i PGN.'}})}
async function refresh(){games=await readAll();stats();list();await weeklyGoal();try{const r=await fetch('vendor/training-catalog.json');if(!r.ok)throw Error('Catalogo non disponibile');const deck=makeDeck(games,await r.json()),s=reviewSummary(deck.cards,await readAll('attempts'));$('reviewOverview').textContent=`${s.due} da ripassare · ${s.new} nuove posizioni · ${s.mastered} consolidate. Le riuscite senza aiuti allungano gli intervalli.`}catch{$('reviewOverview').textContent='Apri Esercizi per vedere il tuo piano di ripasso.'}}
function showProfile(){if(!profile){$('ratings').innerHTML='';$('syncGames').disabled=$('analyzeLatest').disabled=true;return}$('username').value=profile.username;$('ratings').innerHTML=['rapid','blitz','bullet','daily'].map(type=>`<div class="stat"><span>${type}</span><strong>${profile.stats['chess_'+type]?.last?.rating??'—'}</strong></div>`).join('');$('syncGames').disabled=$('analyzeLatest').disabled=false;$('syncStatus').textContent=`Profilo ${profile.username} · letto il ${new Date(profile.fetchedAt).toLocaleString(locale())}. Rating pubblico Chess.com; può non essere in tempo reale.`}
$('username').oninput=()=>{$('syncGames').disabled=$('analyzeLatest').disabled=!profile||$('username').value.trim().toLowerCase()!==profile.username};
async function playerReport(){
 if(!profile){$('playerReport').textContent='Collega il profilo per iniziare.';return}
 const sample=games.filter(g=>g.source==='chess.com'&&[g.headers?.White,g.headers?.Black].some(n=>n?.toLowerCase()===profile.username)).sort((a,b)=>b.playedAt-a.playedAt).slice(0,30),s=personalStats(sample);
 const theme=Object.entries(s.themes).sort((a,b)=>b[1]-a[1])[0];
 $('playerReport').textContent=`${s.analyzed}/${sample.length} partite analizzate. Precisione media: ${fixed(s.accuracy)}. `+(theme?.[1]?`Tema su cui lavorare: ${THEMES[theme[0]]} (${theme[1]} errori). Gli esercizi includono queste posizioni.`:'Completa le analisi per trovare i temi da allenare.')+' È un campione indicativo, non una stima del tuo Elo.';
 await putRecord({id:'player-report-'+profile.username,count:s.analyzed,total:sample.length,theme:theme?.[1]?theme[0]:null},'meta');
}
async function performBatch(task){
 if(controller)return;controller=new AbortController();for(const id of ['connect','disconnect','syncGames','analyzeLatest','username'])$(id).disabled=true;$('cancelSync').hidden=false;
 try{const work=async()=>task(controller.signal);if(navigator.locks)await navigator.locks.request('plystreak-batch',{ifAvailable:true},lock=>{if(!lock)throw Error('Analisi già attiva in un’altra scheda.');return work()});else await work()}
 catch(e){$('syncStatus').textContent=e.message+' I progressi già completati sono salvati.'}
 finally{controller=null;for(const id of ['connect','disconnect','username'])$(id).disabled=false;$('syncGames').disabled=$('analyzeLatest').disabled=!profile;$('cancelSync').hidden=true;await refresh();await playerReport()}
}
async function continueBatch(signal){await runBatch(profile.username,{signal,onProgress:(game,total,ply,moves,verify,eta)=>$('syncStatus').textContent=`Partita ${game}/${total} · mossa ${ply}/${moves}${verify?' · ricontrollo approfondito':''} · ${eta===null?'stima in preparazione':'circa '+Math.max(1,Math.ceil(eta/60000))+' min rimanenti (stima variabile)'}. Puoi interrompere e riprendere.`,onSaved:async()=>{await refresh();await playerReport()}});$('syncStatus').textContent='Analisi completata. Profilo ed esercizi aggiornati. Premi di nuovo per cercare nuove partite.'}
async function latestAndAnalyze(signal,{analyze=false}={}){
 const importStarted=performance.now();
 const previous=await getRecord('batch-'+profile.username,'meta'),since=previous?.lastSeen??null;
 const records=await fetchLatestGames(profile.username,since===null?30:Infinity,{signal,since,onProgress:i=>$('syncStatus').textContent=`Lettura delle partite più recenti · archivio ${i+1}…`}),ids=[];let newest=since;
 for(const record of records){if(signal.aborted)throw Error('Importazione interrotta.');try{const c=new Chess();c.loadPgn(record.pgn);if(!c.history().length)continue}catch{continue}const saved=await saveGame(record);ids.push(saved.id);newest=Math.max(newest||0,saved.playedAt)}
 await putRecord({id:'batch-'+profile.username,ids:[...new Set([...(previous?.ids||[]),...ids])],lastSeen:newest,startedAt:Date.now()},'meta');await refresh();await playerReport();if(!ids.length&&!previous?.ids.length){$('syncStatus').textContent='Nessuna partita standard conclusa disponibile.';return}const queue=await Promise.all([...new Set([...(previous?.ids||[]),...ids])].map(id=>getRecord(id)));const pending=queue.filter(g=>g&&(!g.analysis?.complete||g.analysis.methodId!==ANALYSIS_METHOD));if(!pending.length){$('syncStatus').textContent='Sei aggiornato: nessuna nuova partita da analizzare. Le analisi complete sono state conservate.';return}if(analyze)await continueBatch(signal);else $('syncStatus').textContent=`Importazione completata in ${Math.max(1,Math.round((performance.now()-importStarted)/1000))} s. ${pending.length} partite in attesa di analisi. Puoi già aprirle dall’archivio. Premi Analizza / riprendi per il calcolo approfondito, che può richiedere molto tempo.`;
}
$('connectForm').onsubmit=e=>{e.preventDefault();performBatch(async signal=>{$('syncStatus').textContent='Lettura del profilo pubblico…';profile=await fetchProfile($('username').value.trim(),signal);await putRecord(profile,'meta');localStorage.setItem('plystreak-chess-user',profile.username);showProfile();$('syncGames').disabled=$('analyzeLatest').disabled=true;await latestAndAnalyze(signal)})};
$('analyzeLatest').onclick=()=>{if(!profile)return;performBatch(async signal=>{const job=await getRecord('batch-'+profile.username,'meta'),records=job?await Promise.all(job.ids.map(id=>getRecord(id))):[];if(records.some(g=>g&&(!g.analysis?.complete||g.analysis.methodId!==ANALYSIS_METHOD)))await continueBatch(signal);else await latestAndAnalyze(signal,{analyze:true})})};
window.addEventListener('beforeunload',e=>{if(controller){e.preventDefault();e.returnValue=''}});
$('syncGames').onclick=async()=>{if(!profile||controller)return;controller=new AbortController();$('syncGames').disabled=$('analyzeLatest').disabled=true;$('connect').disabled=true;$('disconnect').disabled=true;$('cancelSync').hidden=false;try{const r=await syncArchive(profile.username,$('syncRange').value,async records=>{let added=0;for(const record of records){await saveGame(record);added++}return added},controller.signal,(i,n,m)=>$('syncStatus').textContent=`Importazione mese ${i+1}/${n} · ${m}. Le partite già presenti non vengono duplicate.`);$('syncStatus').textContent=`Importazione completata: ${r.count} partite lette in ${r.months} mesi; ${r.skipped} partite non standard escluse.`}catch(e){$('syncStatus').textContent=e.message+' I mesi già scaricati rimangono disponibili.'}finally{controller=null;$('syncGames').disabled=$('analyzeLatest').disabled=false;$('connect').disabled=false;$('disconnect').disabled=false;$('cancelSync').hidden=true;await refresh()}};
$('cancelSync').onclick=()=>{controller?.abort();$('syncStatus').textContent='Interrompo dopo il calcolo corrente. I progressi completati restano salvati.'};$('disconnect').onclick=async()=>{if(controller)return;profile=null;await putRecord({id:'chess-profile',disconnected:true},'meta');localStorage.removeItem('plystreak-chess-user');showProfile();await playerReport();await weeklyGoal();$('syncStatus').textContent='Profilo scollegato. Le partite già importate restano nell’archivio.'};
$('gameSearch').oninput=()=>{page=0;list()};$('sourceFilter').onchange=()=>{page=0;list()};$('previousPage').onclick=()=>{page--;list()};$('nextPage').onclick=()=>{page++;list()};
$('backup').onclick=async()=>{const backup={format:'plystreak-backup',version:2,games:await readAll(),attempts:await readAll('attempts'),settings:getSettings(),meta:await readAll('meta')};const url=URL.createObjectURL(new Blob([JSON.stringify(backup)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='plystreak-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)};
$('restore').onchange=async e=>{if(controller){$('hubStatus').textContent='Interrompi l’analisi o l’importazione prima di ripristinare un backup.';e.target.value='';return}const f=e.target.files[0];if(!f)return;try{if(f.size>50000000)throw Error('Il backup supera 50 MB.');const data=validateBackup(JSON.parse(await f.text()));for(const g of data.games)if(!await getRecord(g.id))await saveGame(g);for(const a of data.attempts)if(!await getRecord(a.id,'attempts'))await putRecord(a,'attempts');for(const m of data.meta||[])if(!await getRecord(m.id,'meta'))await putRecord(m,'meta');const preferencesSaved=!$('restorePreferences').checked||!data.settings||saveSettings(data.settings);const restoredProfile=await getRecord('chess-profile','meta');if(restoredProfile&&!restoredProfile.disconnected){profile=restoredProfile;localStorage.setItem('plystreak-chess-user',profile.username);showProfile()}$('hubStatus').textContent='Backup ripristinato: partite, analisi, ripassi e profilo. Record esistenti conservati; preferenze e avatar '+($('restorePreferences').checked?'ripristinati se inclusi.':'conservati.');if(!preferencesSaved)$('hubStatus').textContent+=' Attenzione: le preferenze non sono state salvate sul dispositivo.';await refresh();await playerReport()}catch(e){$('hubStatus').textContent=e.message}e.target.value=''};
(async()=>{try{await refresh();const p=await getRecord('chess-profile','meta');if(p&&!p.disconnected){profile=p;showProfile();await playerReport()}}catch(e){$('hubStatus').textContent=e.message}})();

async function weeklyGoal(){const username=profile?.username||localStorage.getItem('plystreak-chess-user')||'',sample=games.filter(g=>g.source!=='chess.com'||[g.headers?.White,g.headers?.Black].some(n=>n?.toLowerCase()===username));const candidate=createGoal(sample,username),stored=await getRecord(candidate.id,'meta'),goal=stored||candidate;if(!stored&&sample.some(eligible))await putRecord(goal,'meta');const view=goalText(goal,sample);$('weeklyGoal').innerHTML='<h3>'+esc(view.title)+'</h3><p>'+esc(view.action)+'</p><p>'+esc(view.text)+'</p><small>Settimana da lunedì, sul fuso orario del dispositivo. Il tema resta stabile per la settimana. Il confronto usa errori per 100 mosse, non il numero di partite giocate.</small>'}

window.addEventListener('ply-settings',()=>{stats();list();showProfile()});

const refreshLatest=document.createElement("button");refreshLatest.id="refreshLatest";refreshLatest.className="secondary";refreshLatest.textContent="Importa nuove partite";$("analyzeLatest").after(refreshLatest);refreshLatest.onclick=()=>{if(profile&&!controller)performBatch(signal=>latestAndAnalyze(signal));};
